// A toy heap that supports BOTH reference counting and mark-sweep tracing,
// so we can watch how each one handles a reference cycle.
class Heap {
  objects = new Map();   // id -> { refs: Set<id>, rc: number }
  roots = new Set();     // ids referenced from "stack/global" variables

  alloc(id) { this.objects.set(id, { refs: new Set(), rc: 0 }); return id; }

  addRoot(id) { this.roots.add(id); this.objects.get(id).rc++; }
  dropRoot(id) { this.roots.delete(id); this.#decRef(id); }

  link(from, to) { this.objects.get(from).refs.add(to); this.objects.get(to).rc++; }
  unlink(from, to) { this.objects.get(from).refs.delete(to); this.#decRef(to); }

  // Reference counting: free an object the moment its count hits zero,
  // then decrement everything it pointed to (which may cascade).
  #decRef(id) {
    const obj = this.objects.get(id);
    if (!obj || --obj.rc > 0) return;
    this.objects.delete(id);
    console.log(`  RC freed ${id}`);
    for (const child of obj.refs) this.#decRef(child);
  }

  // Tracing: mark everything reachable from the roots, sweep the rest.
  markSweep() {
    const marked = new Set();
    const stack = [...this.roots];
    while (stack.length) {
      const id = stack.pop();
      if (marked.has(id)) continue;
      marked.add(id);
      stack.push(...this.objects.get(id).refs);
    }
    for (const id of [...this.objects.keys()]) {
      if (!marked.has(id)) { this.objects.delete(id); console.log(`  GC swept ${id}`); }
    }
  }

  live() { return [...this.objects.keys()].join(', ') || '(empty)'; }
}

const heap = new Heap();
heap.alloc('app'); heap.alloc('cache'); heap.alloc('parent'); heap.alloc('child');
heap.addRoot('app');
heap.link('app', 'cache');
heap.link('app', 'parent');
heap.link('parent', 'child');
heap.link('child', 'parent');    // child.parent back-pointer -> a cycle

console.log('1) app drops its cache (no cycle):');
heap.unlink('app', 'cache');     // cache rc 1 -> 0, freed immediately

console.log('2) app drops parent (parent <-> child is a cycle):');
heap.unlink('app', 'parent');    // parent rc 2 -> 1: child still points to it
console.log('  live after RC:', heap.live());   // app, parent, child  (leaked!)

console.log('3) run a tracing collection:');
heap.markSweep();                // nothing reaches the cycle from a root
console.log('  live after GC:', heap.live());   // app

// Incremental tri-color marking, and why the mutator needs a write barrier.
// white = not yet seen (garbage if still white at the end)
// grey  = seen, children not yet scanned (the marker's worklist)
// black = seen and all children scanned
function run({ barrier }) {
  const objs = {
    A: { color: 'white', refs: ['B'] },  // A is a root
    B: { color: 'white', refs: ['C'] },
    C: { color: 'white', refs: [] },
  };
  const grey = [];
  const shade = (id) => { if (objs[id].color === 'white') { objs[id].color = 'grey'; grey.push(id); } };

  // One unit of incremental marking work: scan a single grey object.
  const markStep = () => {
    const id = grey.shift();
    objs[id].refs.forEach(shade);
    objs[id].color = 'black';
  };

  // The program ("mutator") writes pointers through this function.
  const writeRef = (from, to, add) => {
    if (add) {
      objs[from].refs.push(to);
      // Dijkstra-style insertion barrier: never let a black object point to a white one
      if (barrier && objs[from].color === 'black') shade(to);
    } else {
      objs[from].refs = objs[from].refs.filter((r) => r !== to);
    }
  };

  shade('A');      // GC starts: roots become grey
  markStep();      // A scanned -> black, B grey   (GC pauses, program runs)

  writeRef('A', 'C', true);   // program: A.c = B.c
  writeRef('B', 'C', false);  // program: B.c = null  -> C now reachable ONLY via black A

  while (grey.length) markStep();  // GC resumes and finishes marking

  const swept = Object.keys(objs).filter((id) => objs[id].color === 'white');
  const stillReferenced = swept.filter((id) => Object.values(objs).some((o) => o.refs.includes(id)));
  return { swept, stillReferenced };
}

console.log('without barrier:', run({ barrier: false }));
// without barrier: { swept: [ 'C' ], stillReferenced: [ 'C' ] }  <- live object freed!
console.log('with barrier:   ', run({ barrier: true }));
// with barrier:    { swept: [], stillReferenced: [] }

// Run with: node --expose-gc weak-refs.js   (exposes global gc() for the demo)
// WeakMap, WeakRef, and FinalizationRegistry observe objects WITHOUT keeping them alive.
const registry = new FinalizationRegistry((label) => {
  console.log(`finalizer ran for: ${label}`);   // timing is up to the engine
});
globalThis.registry = registry;  // a registry that is itself collected never calls back

const metadata = new WeakMap();  // keys are held weakly: entry dies with its key

function createPayload() {
  const big = { payload: new Array(1_000_000).fill(42) };
  metadata.set(big, { createdAt: Date.now() });
  registry.register(big, 'big payload');
  return new WeakRef(big);       // only a weak reference escapes this function
}
const weak = createPayload();

console.log('before gc, alive:', weak.deref() !== undefined);  // before gc, alive: true

// A WeakRef target stays alive until the current synchronous job ends
// (the spec's KeepDuringJob set), so collect in a later macrotask.
setTimeout(async () => {
  globalThis.gc();
  console.log('after gc, deref():', weak.deref());       // after gc, deref(): undefined
  await new Promise((r) => setTimeout(r, 100));         // give cleanup callbacks a chance
  console.log('done');
}, 0);
// Typical output on Node 22+ (finalizer timing is NOT guaranteed by the spec):
// before gc, alive: true
// after gc, deref(): undefined
// finalizer ran for: big payload
// done

// Run with: node --expose-gc leak-demo.js
// Two classic Node.js leaks and their fixes, measured with heapUsed after a full GC.
const { EventEmitter } = require('node:events');

const heapMB = () => { globalThis.gc(); return process.memoryUsage().heapUsed / 2 ** 20; };

// ── Leak 1: an unbounded module-level cache ──
const cache = new Map();
function handleRequestLeaky(id) {
  const result = { id, body: 'x'.repeat(10_000) + id };  // ~10 KB per entry
  cache.set(id, result);       // every unique id is kept forever
  return result.body.length;
}

// Fix: bound the cache (simple LRU using Map insertion order)
const MAX = 100;
const lru = new Map();
function handleRequestBounded(id) {
  const result = { id, body: 'x'.repeat(10_000) + id };
  lru.delete(id);
  lru.set(id, result);                                   // newest at the end
  if (lru.size > MAX) lru.delete(lru.keys().next().value); // evict the oldest
  return result.body.length;
}

// ── Leak 2: listeners added per request and never removed ──
const bus = new EventEmitter();
bus.setMaxListeners(0);   // silences MaxListenersExceededWarning: don't do this to hide a leak!
function subscribeLeaky(id) {
  const ctx = { id, scratch: new Array(1_000).fill(id) }; // captured by the closure
  bus.on('config', () => ctx.id);                         // never removed
}
function subscribeFixed(id) {
  const ctx = { id, scratch: new Array(1_000).fill(id) };
  const handler = () => ctx.id;
  bus.on('config', handler);
  return () => bus.off('config', handler);  // caller unsubscribes when the request ends
}

const base = heapMB();
for (let i = 0; i < 5_000; i++) { handleRequestLeaky(i); subscribeLeaky(i); }
const leaked = heapMB() - base;
const leakedEntries = cache.size;
const leakedListeners = bus.listenerCount('config');

cache.clear(); bus.removeAllListeners(); // reset before measuring the fixed version
const base2 = heapMB();
for (let i = 0; i < 5_000; i++) {
  handleRequestBounded(i);
  const unsubscribe = subscribeFixed(i);
  unsubscribe();                       // request finished
}
const fixed = heapMB() - base2;

console.log(`leaky: +${leaked.toFixed(1)} MB, ${leakedEntries} cache entries, ${leakedListeners} listeners`);
console.log(`fixed: +${fixed.toFixed(1)} MB, ${lru.size} cache entries, ${bus.listenerCount('config')} listeners`);
// Typical output (exact MB varies by Node version and platform):
// leaky: +42.0 MB, 5000 cache entries, 5000 listeners
// fixed: +0.1 MB, 100 cache entries, 0 listeners
console.log('leak retains 20x+ more memory:', leaked > fixed * 20); // true
